def check_v(v, u_limit=100000):
    # Precompute s for the range we need
    # For a given u, we need s from u to u + 2v - 1.
    # The maximum n we will need is u_limit + 2*v.
    max_n = u_limit + 2 * v
    s_vals = [0] * (max_n + 1)
    for n in range(1, max_n + 1):
        temp_n = n
        while temp_n % 2 == 0:
            temp_n //= 2
        s_vals[n] = temp_n % 4

    for u in range(1, u_limit):
        match = True
        for i in range(v):
            if s_vals[u + i] != s_vals[u + v + i]:
                match = False
                break
        if match:
            return True, u
    return False, None

