def check_v(v, u_limit=10000000):
    # To speed up, we can precompute s_vals in chunks
    chunk_size = 1000000
    for start in range(1, u_limit, chunk_size):
        end = min(start + chunk_size, u_limit)
        # We need s_vals from start to end + 2*v
        s_vals = [0] * (end + 2*v - start + 1)
        for n in range(start, end + 2*v):
            temp_n = n
            while temp_n % 2 == 0:
                temp_n //= 2
            s_vals[n - start] = temp_n % 4

        for u in range(start, end):
            match = True
            for i in range(v):
                if s_vals[u - start + i] != s_vals[u - start + v + i]:
                    match = False
                    break
            if match:
                return True, u
    return False, None

